get_settings.code:
const response = await client.commonSettings.getSettings({type: 'customer_registration_field', config_key: 'abn_placeholder'});
for (const setting of response.map.settings.customer_registration_field) {
    console.log(setting.config_key, setting.value);
}

update_settings.code:
const response = await client.commonSettings.updateSettings({
    settings: {
        customer_registration_field: [{config_key: 'abn_placeholder', value: 'Enter your ABN'}],
    },
});
for (const setting of response.map.settings.customer_registration_field) {
    console.log(setting.config_key, setting.value);
}

save_settings.code:
